const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point([38.0, 6.0]).buffer(50000); // Southern Ethiopia, 50km buffer
  const startYearRecent = 2021;
  const endYearRecent = 2021;
  const startYearLTA = 2000;
  const endYearLTA = 2013;
  const startMonth = 10;
  const endMonth = 11;
  const LTA_YEARS = endYearLTA - startYearLTA + 1;

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Recent Period (2021)
  const recentFilter = ee.Filter.date(
    ee.Date.fromYMD(startYearRecent, startMonth, 1),
    ee.Date.fromYMD(endYearRecent, endMonth, 30).advance(1, 'day')
  );
  const recentCollection = chirps.filter(recentFilter).filterBounds(region);

  // Long-Term Average (LTA) Period (2000-2013)
  const ltaFilter = ee.Filter.calendarRange(startMonth, endMonth, 'month');
  const ltaCollection = chirps.filter(ee.Filter.calendarRange(startYearLTA, endYearLTA, 'year'))
                             .filter(ltaFilter)
                             .filterBounds(region);

  // 3. Initial Data Validation
  const recentSize = recentCollection.size().getInfo();
  const ltaSize = ltaCollection.size().getInfo();

  if (recentSize === 0 || ltaSize === 0) {
    console.log(`Recent (2021) image count: ${recentSize}`);
    console.log(`Long-Term (2000-2013) image count: ${ltaSize}`);
    console.log("Empty collection for one or both periods.");
    console.log("A"); // Likely a typo in the question, so this should not happen with CHIRPS
    return;
  }
  console.log(`Recent (2021) image count: ${recentSize}`);
  console.log(`Long-Term (2000-2013) image count: ${ltaSize}`);

  // 4. Processing and Calculation
  // Calculate total rainfall for the recent period
  const recentTotal = recentCollection.sum();

  // Calculate total rainfall for the long-term period
  const ltaTotal = ltaCollection.sum();

  // Calculate the mean annual rainfall for the Oct-Nov period in the LTA
  const ltaMeanAnnual = ltaTotal.divide(LTA_YEARS);

  // Reduce to a single value for the region
  const reducer = ee.Reducer.mean();
  const scale = 5000;

  const recentRainfallStat = recentTotal.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  const ltaRainfallStat = ltaMeanAnnual.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  // Must evaluate the results on the server before using them
  const recentRainfall = ee.Number(recentRainfallStat).getInfo();
  const ltaRainfall = ee.Number(ltaRainfallStat).getInfo();

  // 5. Validation and Final Answer
  if (recentRainfall === null || ltaRainfall === null || isNaN(recentRainfall) || isNaN(ltaRainfall)) {
      console.log(`Recent Rainfall calculation returned: ${recentRainfall}`);
      console.log(`LTA Rainfall calculation returned: ${ltaRainfall}`);
      console.log("C3");
      return;
  }

  if(recentRainfall === 0 && ltaRainfall === 0){
      console.log("Both periods have zero rainfall, unable to determine if 'less'.");
      console.log("C2");
      return;
  }

  console.log(`Rainfall Oct-Nov 2021 (mm): ${recentRainfall.toFixed(2)}`);
  console.log(`Long-Term Avg Oct-Nov 2000-2013 (mm): ${ltaRainfall.toFixed(2)}`);

  if (recentRainfall < ltaRainfall) {
    console.log("2021 rainfall was less than the long-term average.");
    console.log("A");
  } else {
    console.log("2021 rainfall was not less than the long-term average.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred: ", err);
    console.log("D");
});
